// Only a trusted internal caller should reach this authenticated webhook.
// This is schema validation, NOT tenant authorization or consent verification.
const body = $input.first().json.body ?? {};
const errors = [];
const isId = (v) => typeof v === 'string' && v.length >= 8 && v.length <= 128;
if (!isId(body.tenantId)) errors.push('tenantId is required');
if (!isId(body.customerId)) errors.push('customerId is required');
if (!isId(body.clientMessageId)) errors.push('clientMessageId is required');
if (body.conversationId !== undefined && body.conversationId !== null && !isId(body.conversationId)) errors.push('conversationId must be an identifier');
const text = typeof body.text === 'string' ? body.text.trim() : '';
if (text.length > 12000) errors.push('text too long');
const documentIds = Array.isArray(body.documentIds) ? body.documentIds : [];
if (!documentIds.every(isId) || documentIds.length > 10) errors.push('invalid documentIds');
if (!text && documentIds.length === 0) errors.push('text or existing documentIds required');
return [{json: {valid: errors.length === 0, error: {code: 'INVALID_INPUT', details: errors}, payload: {
  tenantId: body.tenantId, customerId: body.customerId,
  conversationId: body.conversationId ?? null,
  clientMessageId: body.clientMessageId, text, documentIds
}}}];
